            PhaseClientId: LookUp(colWfDraftPhases, PhaseKey = a.PhaseKey).ClientId,
            AssignmentKey: a.AssignmentKey,
            AssignmentOrder: a.AssignmentOrder,
            AssigneeName: a.AssigneeName,
            AssigneeEmail: a.AssigneeEmail,
