            Goal: a.Goal,
            Required: a.Required,
            DurationDays: a.DurationDays,
            IsGroup: a.IsGroup,
            GroupId: a.GroupId,
            StatusKey: a.StatusKey,
            IsNew: false,
            IsRemoved: false
        }
    )
);
